import{_ as i,o as t,c as s,a2 as a}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Civilisation intensive est-asiatique","description":"","frontmatter":{},"headers":[],"relativePath":"fr/0031-东亚集约型文明.md","filePath":"fr/0031-东亚集约型文明.md"}'),n={name:"fr/0031-东亚集约型文明.md"};function l(o,e,r,c,u,d){return t(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="civilisation-intensive-est-asiatique" tabindex="-1">Civilisation intensive est-asiatique <a class="header-anchor" href="#civilisation-intensive-est-asiatique" aria-label="Permalink to &quot;Civilisation intensive est-asiatique&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Élément</th><th>Contenu</th></tr></thead><tbody><tr><td>N° de document</td><td>31</td></tr><tr><td>Module</td><td>Typologies de civilisations et systèmes sociaux</td></tr><tr><td>Mots-clés</td><td>Intensif est-asiatique, Priorité collective, Culture à grande échelle, Exécution efficace, Héritage familial</td></tr></tbody></table><h2 id="i-origines-et-concepts-centraux-de-la-civilisation-intensive-est-asiatique" tabindex="-1">I. Origines et concepts centraux de la civilisation intensive est-asiatique <a class="header-anchor" href="#i-origines-et-concepts-centraux-de-la-civilisation-intensive-est-asiatique" aria-label="Permalink to &quot;I. Origines et concepts centraux de la civilisation intensive est-asiatique&quot;">​</a></h2><p>La civilisation intensive est-asiatique est la plus collectiviste des cinq typologies de civilisations symbiotiques, avec des origines remontant aux millénaires de traditions civilisatrices des régions d&#39;Asie de l&#39;Est dans le monde réel. Par un long développement historique, les régions d&#39;Asie de l&#39;Est ont formé des caractéristiques civilisatrices centrées sur le collectif, basées sur l&#39;unité familiale et fondées sur l&#39;ordre. Après l&#39;établissement de la Civilisation Symbiotique de l&#39;Ancre, cette tradition s&#39;est combinée avec les concepts symbiotiques et a été améliorée pour créer la forme civilisatrice unique de la « civilisation intensive est-asiatique ».</p><p>Le concept central de la civilisation intensive est-asiatique peut se résumer en huit caractères : « priorité collective, efficacité intensive ». Plus précisément :</p><ol><li><strong>Priorité collective</strong> : dans la relation entre l&#39;individu et le collectif, il souligne que les intérêts collectifs sont au-dessus des intérêts individuels, et que le développement individuel doit s&#39;intégrer dans le développement collectif. Les collectifs familiaux, sectaires et communautaires sont les cellules de base de la société ; les individus réalisent leur propre valeur en contribuant au collectif</li><li><strong>Efficacité intensive</strong> : dans la répartition des ressources, il souligne la réalisation d&#39;une utilisation intensive et d&#39;une allocation efficace des ressources par la planification globale collective. Il s&#39;oppose aux constructions répétitives dispersées et de faible niveau, et prône la concentration des forces pour accomplir de grandes tâches</li><li><strong>Ordre et harmonie</strong> : dans les relations sociales, il souligne un ordre social hiérarchique respectueux des aînés, poursuivant une coexistence harmonieuse entre les personnes</li><li><strong>Diligence et entreprise</strong> : dans les qualités individuelles, il prône la diligence, la frugalité, la persévérance et l&#39;entreprise, croyant que le destin peut être changé par un effort inlassable</li></ol><p>Ces concepts de la civilisation intensive est-asiatique sont hautement compatibles avec les concepts centraux de la Civilisation Symbiotique de l&#39;Ancre : « À Chacun Selon son Travail », « croissance spontanée », « Un Chemin pour Chacun » et « progression commune des Dix Mille Races ». La priorité collective garantit la réalisation de la « progression commune des Dix Mille Races », l&#39;efficacité intensive garantit l&#39;efficacité de « À Chacun Selon son Travail », et la diligence et l&#39;entreprise sont l&#39;incarnation vivante de la « croissance spontanée ».</p><h2 id="ii-la-structure-sociale-de-la-civilisation-intensive-est-asiatique" tabindex="-1">II. La structure sociale de la civilisation intensive est-asiatique <a class="header-anchor" href="#ii-la-structure-sociale-de-la-civilisation-intensive-est-asiatique" aria-label="Permalink to &quot;II. La structure sociale de la civilisation intensive est-asiatique&quot;">​</a></h2><p>La structure sociale de la civilisation intensive est-asiatique prend le collectif à trois niveaux « famille—secte—communauté » comme cadre de base, formant un réseau social emboîté et étroitement connecté :</p><table tabindex="0"><thead><tr><th>Niveau</th><th>Unité</th><th>Taille</th><th>Fonction centrale</th><th>Méthode de répartition des ressources</th></tr></thead><tbody><tr><td>Niveau 1</td><td>Famille</td><td>Des dizaines à des centaines de personnes</td><td>Sécurité de subsistance de base, liens de parenté, éducation d&#39;initiation</td><td>Distribution intra-familiale selon les besoins</td></tr><tr><td>Niveau 2</td><td>Secte</td><td>Des centaines à des dizaines de milliers</td><td>Formation professionnelle de culture, R&amp;D technologique, gestion des ressources</td><td>Distribution intra-sectaire selon le travail</td></tr><tr><td>Niveau 3</td><td>Communauté</td><td>Des dizaines de milliers à des millions</td><td>Services publics, infrastructures, gouvernance sociale</td><td>Coordination communautaire + ajustement du marché</td></tr></tbody></table><h3 id="_2-1-famille" tabindex="-1">2.1 Famille <a class="header-anchor" href="#_2-1-famille" aria-label="Permalink to &quot;2.1 Famille&quot;">​</a></h3><p>La famille est l&#39;unité sociale la plus fondamentale de la civilisation intensive est-asiatique, généralement composée de dizaines à des centaines de personnes liées par le sang. La famille assume les fonctions centrales suivantes :</p><ul><li><strong>Sécurité de subsistance de base</strong> : les membres de la famille s&#39;entraident, assurant que les besoins vitaux de base de chaque membre sont satisfaits</li><li><strong>Liens de parenté</strong> : maintenir les liens émotionnels entre les membres par des rituels familiaux, des réunions de famille et d&#39;autres activités</li><li><strong>Éducation d&#39;initiation</strong> : les aînés de la famille sont responsables de l&#39;éducation d&#39;initiation des jeunes, y compris les connaissances de base, l&#39;entrée en culture et la culture morale</li><li><strong>Accumulation des ressources</strong> : la famille accumule conjointement la richesse et les ressources de culture, fournissant un soutien au développement des membres</li></ul><p>La répartition des ressources au sein de la famille suit le principe de combinaison « distribution selon les besoins + distribution selon le travail » — les besoins vitaux de base sont distribués selon les besoins, tandis que les ressources de culture supplémentaires et les récompenses sont distribuées selon les contributions individuelles à la famille.</p><h3 id="_2-2-secte" tabindex="-1">2.2 Secte <a class="header-anchor" href="#_2-2-secte" aria-label="Permalink to &quot;2.2 Secte&quot;">​</a></h3><p>La secte est l&#39;unité centrale de la civilisation intensive est-asiatique assumant la formation professionnelle de culture et la R&amp;D technologique, généralement composée de centaines à des dizaines de milliers de personnes ayant des orientations de culture ou des expertises techniques communes. Les fonctions centrales de la secte comprennent :</p><ul><li><strong>Formation professionnelle de culture</strong> : la secte possède un système de culture complet et une équipe de mentors, responsable de la formation professionnelle systématique des disciples</li><li><strong>R&amp;D technologique</strong> : la secte concentre ses forces sur la R&amp;D et l&#39;innovation dans la technologie de culture et la technologie d&#39;ingénierie</li><li><strong>Gestion des ressources</strong> : la secte obtient des revenus en exploitant les ressources de culture et en fournissant des services techniques, soutenant son fonctionnement et son développement</li><li><strong>Exportation de talents</strong> : les talents exceptionnels formés par la secte peuvent entrer dans des institutions de niveau supérieur, contribuant au développement de la communauté et de la civilisation</li></ul><p>La répartition des ressources au sein de la secte suit le principe de la « distribution selon le travail » comme forme principale — les disciples reçoivent des allocations de ressources correspondantes selon leurs réalisations de culture et leurs contributions à la secte. La secte a généralement une hiérarchie stricte, des disciples externes, disciples internes, disciples centraux aux anciens et au maître de secte, avec des niveaux clairs et une promotion ordonnée.</p><h3 id="_2-3-communaute" tabindex="-1">2.3 Communauté <a class="header-anchor" href="#_2-3-communaute" aria-label="Permalink to &quot;2.3 Communauté&quot;">​</a></h3><p>La communauté est l&#39;unité sociale de plus haut niveau de la civilisation intensive est-asiatique, généralement composée de dizaines de milliers à des millions de personnes, couvrant une certaine zone géographique. Les fonctions centrales de la communauté comprennent :</p><ul><li><strong>Services publics</strong> : fournir des services publics tels que l&#39;éducation, la santé, le logement et l&#39;environnement</li><li><strong>Infrastructures</strong> : construire et maintenir des infrastructures telles que les ancres, les canaux d&#39;énergie et les réseaux de transport</li><li><strong>Gouvernance sociale</strong> : maintenir l&#39;ordre social, arbitrer les différends et appliquer les lois</li><li><strong>Coordination des ressources</strong> : coordonner les ressources de culture dans la juridiction, effectuant une répartition des ressources au niveau macro</li></ul><p>La répartition des ressources au niveau de la communauté suit le principe de « coordination + marché » — les ressources publiques de base sont allouées par la coordination communautaire, tandis que les ressources non fondamentales sont ajustées par des mécanismes de marché.</p><h2 id="iii-le-modele-de-culture-de-la-civilisation-intensive-est-asiatique" tabindex="-1">III. Le modèle de culture de la civilisation intensive est-asiatique <a class="header-anchor" href="#iii-le-modele-de-culture-de-la-civilisation-intensive-est-asiatique" aria-label="Permalink to &quot;III. Le modèle de culture de la civilisation intensive est-asiatique&quot;">​</a></h2><p>Le modèle de culture de la civilisation intensive est-asiatique prend « à grande échelle, standardisé, systématisé » comme caractéristiques centrales, capable de former de grands nombres de cultivateurs qualifiés en peu de temps :</p><h3 id="_3-1-culture-a-grande-echelle" tabindex="-1">3.1 Culture à grande échelle <a class="header-anchor" href="#_3-1-culture-a-grande-echelle" aria-label="Permalink to &quot;3.1 Culture à grande échelle&quot;">​</a></h3><p>La civilisation intensive est-asiatique excelle dans la formation de talents à grande échelle par le système sectaire. Une grande secte peut simultanément former des dizaines de milliers de disciples, réalisant une production à grande échelle de talents de culture par un programme standardisé et un modèle d&#39;enseignement à la chaîne. L&#39;avantage de ce modèle de culture est une haute efficacité et une large couverture, capable d&#39;élever rapidement les niveaux de culture globaux.</p><h3 id="_3-2-systeme-standardise" tabindex="-1">3.2 Système standardisé <a class="header-anchor" href="#_3-2-systeme-standardise" aria-label="Permalink to &quot;3.2 Système standardisé&quot;">​</a></h3><p>La civilisation intensive est-asiatique met l&#39;accent sur la construction standardisée des systèmes de culture. Après leur introduction dans la civilisation intensive est-asiatique, les Trois Cents Systèmes de Culture de l&#39;Origine sont généralement raffinés en manuels de culture standardisés, programmes d&#39;enseignement et normes d&#39;évaluation. Chaque étape de culture a des objectifs, un contenu et des méthodes d&#39;évaluation clairs, assurant la stabilité de la qualité de la culture.</p><h3 id="_3-3-heritage-mentor-disciple" tabindex="-1">3.3 Héritage mentor-disciple <a class="header-anchor" href="#_3-3-heritage-mentor-disciple" aria-label="Permalink to &quot;3.3 Héritage mentor-disciple&quot;">​</a></h3><p>Malgré l&#39;accent mis sur l&#39;échelle et la standardisation, la civilisation intensive est-asiatique accorde toujours une grande importance à l&#39;héritage mentor-disciple. Après leur entrée dans la secte, chaque disciple se voit attribuer un mentor, responsable de l&#39;orientation quotidienne et de la culture morale du disciple. Les disciples au talent exceptionnel sont également pris comme « disciples directs », recevant une orientation attentive individuelle du mentor. Cette combinaison « grande échelle + personnalisation » assure à la fois l&#39;efficacité de la formation et l&#39;adaptation au développement personnalisé des talents.</p><h3 id="_3-4-evaluation-et-promotion" tabindex="-1">3.4 Évaluation et promotion <a class="header-anchor" href="#_3-4-evaluation-et-promotion" aria-label="Permalink to &quot;3.4 Évaluation et promotion&quot;">​</a></h3><p>La civilisation intensive est-asiatique a établi un système strict d&#39;évaluation et de promotion. Les disciples doivent participer régulièrement aux évaluations, dont le contenu comprend le niveau de culture, la capacité de combat pratique, les connaissances théoriques, la culture morale, etc. Ceux qui réussissent l&#39;évaluation peuvent être promus, obtenant plus d&#39;allocations de ressources et un statut plus élevé ; ceux qui échouent doivent redoubler, ou peuvent même être éliminés. Ce système stimule à la fois l&#39;esprit d&#39;entreprise des disciples et garantit la qualité de la formation des talents.</p><h2 id="iv-le-mecanisme-de-contrat-lie-a-la-production-de-la-civilisation-intensive-est-asiatique" tabindex="-1">IV. Le mécanisme de contrat lié à la production de la civilisation intensive est-asiatique <a class="header-anchor" href="#iv-le-mecanisme-de-contrat-lie-a-la-production-de-la-civilisation-intensive-est-asiatique" aria-label="Permalink to &quot;IV. Le mécanisme de contrat lié à la production de la civilisation intensive est-asiatique&quot;">​</a></h2><p>Le mécanisme de contrat lié à la production de la civilisation intensive est-asiatique prend la « sous-traitance collective » comme forme principale, clairement différente des autres typologies :</p><ol><li><strong>Unité de sous-traitance</strong> : les unités collectives telles que les familles et les sectes sont les sujets de sous-traitance, plutôt que les individus</li><li><strong>Contenu de la sous-traitance</strong> : les unités collectives sous-traitent des tâches de la communauté telles que le développement des ressources de culture dans une certaine zone, la maintenance des ancres et la R&amp;D technologique</li><li><strong>Distribution interne</strong> : après avoir obtenu les revenus de la sous-traitance, l&#39;unité collective effectue une distribution secondaire en interne, équilibrant l&#39;accumulation collective et les retours individuels</li><li><strong>Responsabilité conjointe</strong> : les membres de l&#39;unité collective portent une responsabilité conjointe ; la performance excellente d&#39;un membre peut apporter des récompenses au collectif, tandis que la violation d&#39;un membre peut affecter la note du collectif</li></ol><p>L&#39;avantage de ce mécanisme de « sous-traitance collective » est sa capacité à exploiter l&#39;effet d&#39;échelle et les avantages de collaboration du collectif, améliorant l&#39;efficacité de l&#39;utilisation des ressources ; il renforce également la cohésion du collectif et le sentiment d&#39;appartenance des membres.</p><h2 id="v-avantages-et-defis-de-la-civilisation-intensive-est-asiatique" tabindex="-1">V. Avantages et défis de la civilisation intensive est-asiatique <a class="header-anchor" href="#v-avantages-et-defis-de-la-civilisation-intensive-est-asiatique" aria-label="Permalink to &quot;V. Avantages et défis de la civilisation intensive est-asiatique&quot;">​</a></h2><h3 id="_5-1-avantages-typiques" tabindex="-1">5.1 Avantages typiques <a class="header-anchor" href="#_5-1-avantages-typiques" aria-label="Permalink to &quot;5.1 Avantages typiques&quot;">​</a></h3><ul><li><strong>Exécution forte</strong> : la tradition collectiviste et la hiérarchie stricte assurent que les décisions peuvent être exécutées rapidement et efficacement</li><li><strong>Haute efficacité</strong> : la répartition intensive des ressources et la formation de talents à grande échelle réalisent une haute efficacité de développement</li><li><strong>Cohésion forte</strong> : la connexion étroite des familles et des sectes forme une forte cohésion sociale</li><li><strong>Stabilité élevée</strong> : une structure sociale ordonnée et des relations interpersonnelles harmonieuses garantissent une stabilité sociale à long terme</li></ul><h3 id="_5-2-defis-rencontres" tabindex="-1">5.2 Défis rencontrés <a class="header-anchor" href="#_5-2-defis-rencontres" aria-label="Permalink to &quot;5.2 Défis rencontrés&quot;">​</a></h3><ul><li><strong>Espace individuel insuffisant</strong> : l&#39;accent excessif sur le collectif peut comprimer l&#39;espace libre des individus, affectant la créativité et la diversité individuelles</li><li><strong>Dynamique d&#39;innovation faible</strong> : les modèles de culture standardisés peuvent limiter la pensée innovante, nécessitant un équilibre entre normes et innovation</li><li><strong>Risque de rigidité des classes</strong> : les hiérarchies strictes sans mécanismes de mobilité peuvent conduire à la sclérose des classes</li><li><strong>Pression concurrentielle plus forte</strong> : des mécanismes intenses d&#39;évaluation et de promotion peuvent apporter une plus grande pression psychologique aux individus</li></ul><p>En réponse à ces défis, la civilisation intensive est-asiatique absorbe activement les avantages d&#39;autres typologies, comme l&#39;introduction du mécanisme d&#39;incitation à l&#39;innovation du type pluraliste nord-américain et du système de soutien psychologique du type providence nordique, optimisant continuellement sa conception institutionnelle.</p><h2 id="conclusion" tabindex="-1">Conclusion <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusion&quot;">​</a></h2><p>La civilisation intensive est-asiatique est la typologie de civilisation la plus collectiviste de la Civilisation Symbiotique de l&#39;Ancre. Avec le concept central de « priorité collective, efficacité intensive », elle réalise un développement efficace et une forte cohésion par la structure sociale à trois niveaux famille—secte—communauté, le modèle de culture à grande échelle standardisé et le mécanisme de contrat lié à la production à sous-traitance collective. Tout en maintenant ses propres caractéristiques, la civilisation intensive est-asiatique absorbe également en continu les avantages d&#39;autres typologies, évoluant vers une direction plus équilibrée et plus inclusive.</p><h2 id="documents-associes" tabindex="-1">Documents associés <a class="header-anchor" href="#documents-associes" aria-label="Permalink to &quot;Documents associés&quot;">​</a></h2><ul><li>30-五种共生文明分型总览 (Aperçu des cinq typologies de civilisations symbiotiques)</li><li>36-社会结构与阶层流动 (Structure sociale et mobilité des classes)</li><li>37-共生教育体系 (Système d&#39;éducation symbiotique)</li></ul>',46)])])}const v=i(n,[["render",l]]);export{p as __pageData,v as default};
